// The Webflow node returns API v2 items straight through, so every custom
// field sits under fieldData keyed by its slug. Reading $json.rating instead of
// $json.fieldData.rating is undefined on every row, and the diff below would
// then treat every listing as changed.
const cfg = $('Settings').first().json;
const urlField = String(cfg.field_maps_url || '');
const ratingField = String(cfg.field_rating || '');
const reviewsField = String(cfg.field_reviews || '');
const maxListings = Number(cfg.max_listings) || 25;

if (!urlField) {
  throw new Error('Set field_maps_url in Settings to the slug that holds each listing\'s Google Maps URL.');
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const fd = j.fieldData || j;
  const mapsUrl = String(fd[urlField] || '').trim();
  // A listing with no Maps URL cannot be refreshed. It is carried as a skip
  // rather than dropped, so the digest can name what it could not check.
  if (!mapsUrl.startsWith('http')) continue;
  out.push({
    item_id: j.id || j._id || '',
    name: String(fd.name || fd.slug || 'Unnamed listing'),
    maps_url: mapsUrl,
    known_rating: Number(fd[ratingField]) || 0,
    known_reviews: Number(fd[reviewsField]) || 0,
  });
}

const picked = out.slice(0, maxListings);

// Never return zero items. A Code node that emits nothing ends the branch, so
// the quiet path would never run and an empty collection would look exactly
// like a broken workflow. The marker carries no maps_url, which the IF routes
// on.
if (!picked.length) {
  return [{ json: { nothing_to_refresh: true, items_seen: $input.all().length } }];
}

// One Bright Data call for the whole batch rather than one per listing.
return [{ json: {
  payload: picked.map((p) => ({ url: p.maps_url })),
  listings: picked,
  maps_url: picked[0].maps_url,
} }];

// single-item input: the trigger endpoint answers once with one snapshot id.
const res = $input.first().json;

// Bright Data answers validation errors with HTTP 200 and an error body, and
// this node runs with neverError, so an unchecked response looks like a success
// and fails several nodes later blaming the wrong thing.
if (res.error || res.errors) {
  throw new Error('Bright Data rejected the fetch: ' + JSON.stringify(res.error || res.errors));
}
if (!res.snapshot_id) {
  throw new Error('No snapshot_id in the Bright Data response: ' + JSON.stringify(res).slice(0, 400));
}

return [{ json: { snapshot_id: res.snapshot_id } }];

const MAX_POLLS = 20; // 20 x 15s = about 5 minutes

// single-item input: the progress endpoint returns one status object.
const res = $input.first().json;
const snapshotId = $('Check Fetch Accepted').first().json.snapshot_id;
const attempt = $runIndex + 1;

if (res.error) {
  throw new Error('Progress check failed: ' + JSON.stringify(res.error));
}
if (res.status === 'failed') {
  throw new Error('Bright Data reported the snapshot failed: ' + JSON.stringify(res).slice(0, 400));
}
// Without this cap the false branch loops back to the Wait node forever and a
// stuck snapshot spins all night. One listing measured 36 seconds.
if (res.status !== 'ready' && attempt >= MAX_POLLS) {
  throw new Error(
    'Snapshot ' + snapshotId + ' still ' + res.status + ' after ' + attempt +
    ' polls. Raise MAX_POLLS or lower max_listings.'
  );
}

return [{ json: { status: res.status, snapshot_id: snapshotId, attempt, records: res.records || 0 } }];

// Matches the fresh Maps rows back onto the CMS listings by URL. Bright Data
// echoes the requested URL on every row, and rows can come back in a different
// order from the one they were sent in - and some may not come back at all - so
// this cannot be a positional join the way an extractor's output has to be.
const cfg = $('Settings').first().json;
const listings = $('Build Refresh List').first().json.listings || [];
const minRating = Number(cfg.min_rating_change) || 0.1;
const minReviews = Number(cfg.min_reviews_change) || 5;

function normalise(u) {
  return String(u || '').split('?')[0].replace(/\/$/, '');
}

const fresh = {};
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.error || !r.name) continue;
  // `input.url` is what was asked for; `url` is what Google served back, and
  // the two differ once Google appends its own tracking parameters.
  const key = normalise((r.input && r.input.url) || r.url);
  if (key) fresh[key] = r;
}

const changed = [];
const missing = [];
for (const listing of listings) {
  const r = fresh[normalise(listing.maps_url)];
  if (!r) {
    missing.push(listing.name);
    continue;
  }

  const rating = Number(r.rating) || 0;
  const reviews = Number(r.reviews_count) || 0;
  const reasons = [];

  if (r.permanently_closed) {
    // Never rewritten automatically. Unpublishing someone's business is a
    // decision, so this is reported and left for a person.
    reasons.push('Google reports this business as permanently closed');
  }
  if (listing.known_rating && Math.abs(rating - listing.known_rating) >= minRating) {
    reasons.push('rating ' + listing.known_rating + ' to ' + rating);
  } else if (!listing.known_rating && rating) {
    reasons.push('rating not recorded before, now ' + rating);
  }
  if (Math.abs(reviews - listing.known_reviews) >= minReviews) {
    reasons.push('reviews ' + listing.known_reviews + ' to ' + reviews);
  }

  if (!reasons.length) continue;

  changed.push({
    ...listing,
    new_rating: rating,
    new_reviews: reviews,
    phone: r.phone_number || '',
    website: r.open_website || '',
    category: r.category || '',
    is_claimed: r.is_claimed === true,
    permanently_closed: r.permanently_closed === true,
    change_reasons: reasons,
    missing_count: 0,
  });
}

// Same rule as above: this filter must never empty the branch, or the quiet
// path never runs.
if (!changed.length) {
  return [{ json: {
    nothing_changed: true,
    checked: listings.length,
    missing: missing.length,
  } }];
}
changed[0].missing_count = missing.length;
changed[0].missing_names = missing.slice(0, 5);
return changed.map((c) => ({ json: c }));

