// The Information Extractor does not merge its answer into the item, it
// REPLACES it - every row arrives as {output: {...}} and nothing else. The item
// id is gone by this point, so the join back is positional, on the same order
// the extractor received. Matching on a field that no longer exists finds
// nothing and would send an update with no id to write to.
const cfg = $('Settings').first().json;
const dryRun = !(cfg.dry_run === false || cfg.dry_run === 'false');
const source = $('Compare Against Directory').all().map((x) => x.json);
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const src = source[i];
  if (!src || !src.item_id) continue;
  const j = items[i].json || {};
  const a = (j.output && typeof j.output === 'object') ? j.output : j;

  const blurb = String(a.blurb || '').trim().slice(0, 300);
  // A closed business is reported and never written. Everything else is
  // written only when dry_run is off.
  const hold = src.permanently_closed
    ? 'reported closed, left for a person to decide'
    : (!blurb ? 'the model returned no blurb' : '');

  out.push({
    ...src,
    new_blurb: blurb,
    hold_reason: hold,
    should_write: Boolean(!dryRun && !hold),
  });
}

if (!out.length) {
  return [{ json: { nothing_changed: true } }];
}
return out;

// Reads the assembled rows by name rather than from this node's input so the
// digest is identical whether or not anything was written.
const cfg = $('Settings').first().json;
const rows = $('Assemble Updates').all().map((x) => x.json).filter((r) => r.item_id);
const dryRun = !(cfg.dry_run === false || cfg.dry_run === 'false');

if (!rows.length) {
  return [{ json: { message: 'Directory refresh ran and found nothing worth changing.', rows: [] } }];
}

const writing = rows.filter((r) => r.should_write);
const closed = rows.filter((r) => r.permanently_closed);
const lines = [
  '*Webflow directory refresh* - ' + rows.length + ' listing' + (rows.length === 1 ? '' : 's') + ' moved, ' +
    (dryRun ? 'nothing written (dry_run is on)' : writing.length + ' written back'),
];
if (closed.length) {
  lines.push(':warning: ' + closed.length + ' reported permanently closed, left untouched for you to decide.');
}
if (rows[0].missing_count) {
  lines.push('Google returned nothing for ' + rows[0].missing_count + ' listing(s): ' + (rows[0].missing_names || []).join(', '));
}
lines.push('');

for (const r of rows) {
  lines.push('*' + r.name + '*  ' + r.change_reasons.join(', '));
  lines.push('   ' + (r.new_blurb || '(no blurb)'));
  lines.push('   ' + (r.should_write ? '_written to Webflow_' : '_held: ' + (r.hold_reason || 'dry_run on') + '_'));
  lines.push('');
}

return [{ json: { message: lines.join('\n'), rows } }];

// Optional. Splice between 'Download Fresh Listings' and 'Compare Against
// Directory'. Google Maps keeps returning a place after it shuts, so a
// directory that only syncs fields will quietly keep advertising dead venues.
return items.map((item) => {
  const j = item.json || {};
  const closed = j.permanently_closed === true || /permanently closed/i.test(String(j.status || ''));
  return { json: { ...j, permanently_closed: closed, suggested_action: closed ? 'archive' : 'update' } };
});
